class ZipArchive(object):

    def _valid_time_stamp(self, timestamp):
        epoch = (1980, 1, 1, 0, 0, 0, 0, 0, 0)
        match = re.fullmatch(r'(\d{4})(\d{2})(\d{2})\.(\d{2})(\d{2})(\d{2})', timestamp)
        if not match:
            return epoch

        parts = tuple(int(part) for part in match.groups())
        if not 1980 <= parts[0] <= 2107:
            return epoch
        try:
            return datetime.datetime(*parts).timetuple()
        except ValueError:
            return epoch

